  const pulse=0.05*Math.sin(t*0.7)*Math.sin(dist*0.02-t*0.3);
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+pulse)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+spiral2+reaction*0.3)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.5)*Math.sin(sy*0.22+t*0.3)*0.3)*1.5)*0.3;
  const blend=reaction*0.5+reaction2*0.25+cell*0.25,v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,35,85],[12,65,105],[15,100,120],[20,140,130],[60,170,120],[140,190,90],[200,195,60],[220,160,50],[215,110,55],[190,65,60],[140,35,55],[85,20,50],[45,15,55],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
